"use client";
import {useState} from 'react';
import {ShieldCheck,ShieldAlert,Save,Bot,FlaskConical} from 'lucide-react';
import {useAdaptive} from '../../components/AdaptiveProvider';
import {useDemoVault} from '../../components/DemoVaultProvider';
import {CENT,DEMO_RECIPIENT,validAddress,statusLabel,reasonLabel} from '../../lib/demo-vault';
import {parseUsdc,validPolicy,type Agent,type AgentPolicy} from '../../lib/agentvault-policy';
import './adaptive-policies.css';
const money=(n:number)=>(n/1e6).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2});
function readAmount(s:string){if(!/^\d+([.,]\d{1,2})?$/.test(s.trim()))throw Error('En fazla iki ondalık basamaklı tutar girin.');const n=parseUsdc(s);if(n>1e12)throw Error('Demo üst sınırı 1 milyon USDC.');return n;}
function PolicyEditor({agent}:{agent:Agent}){
 const {savePolicy}=useDemoVault();const {preferences}=useAdaptive();
 const p=agent.policy;
 const [daily,setDaily]=useState(String(p.dailyLimit/1e6)),[min,setMin]=useState(String(p.minTransfer/1e6)),[max,setMax]=useState(String(p.maxTransfer/1e6)),[total,setTotal]=useState(String(p.totalLimit/1e6));
 const [allowed,setAllowed]=useState(p.allowlist.join('\n')),[denied,setDenied]=useState(p.denylist.join('\n')),[restricted,setRestricted]=useState(p.allowlistEnabled);
 const [notice,setNotice]=useState(''),[error,setError]=useState('');
 const [reveal,setReveal]=useState(false);
 function addresses(s:string){const a=[...new Set(s.split(/\s+/).filter(Boolean))];if(a.length>20||a.some(x=>!validAddress(x)))throw Error('Her listeye en fazla 20 geçerli Solana adresi girin.');return a;}
 function save(){setError('');setNotice('');try{const next:AgentPolicy={dailyLimit:readAmount(daily),minTransfer:readAmount(min),maxTransfer:readAmount(max),totalLimit:readAmount(total),allowlistEnabled:restricted,allowlist:addresses(allowed),denylist:addresses(denied)};if(!validPolicy(next))throw Error('Minimum ≤ maksimum; maksimum ≤ günlük ve toplam limit olmalıdır. Maksimum, günlük ve toplam limit sıfır olamaz.');savePolicy(agent.id,next);setNotice('Demo asistan kuralları kaydedildi.');}catch(e){setError(e instanceof Error?e.message:'Kayıt yapılamadı.');}}
 if(preferences.hideBalance&&!reveal)return <section className="adaptive-card adaptive-stack"><p>Finansal tutarlar gizli. Kuralları düzenlemek için tutarları bu formda görünür yapın.</p><button className="adaptive-button adaptive-button-secondary" onClick={()=>setReveal(true)}>Limitleri bu formda göster</button></section>;
 return <section className="adaptive-card adaptive-stack"><h2 className="adaptive-section-heading">Agent harcama kuralları</h2><p className="adaptive-small">Her asistanın ayrı yetki sınırı vardır. Günlük limit UTC gününe göre sıfırlanır; toplam limit birikimli harcamadır.</p><div className="policy-grid">{([{label:'Günlük toplam limit',v:daily,set:setDaily},{label:'Minimum işlem tutarı',v:min,set:setMin},{label:'Maksimum işlem tutarı',v:max,set:setMax},{label:'Toplam yetki limiti',v:total,set:setTotal}]).map(f=><label key={f.label} className="adaptive-stack adaptive-label">{f.label} (USDC)<input inputMode="decimal" className="adaptive-input" value={f.v} onChange={e=>f.set(e.target.value)} disabled={agent.status==='revoked'}/></label>)}</div><div className="adaptive-divider"/><label className="adaptive-row"><input type="checkbox" checked={restricted} onChange={e=>setRestricted(e.target.checked)}/> Yalnızca izin verilen adreslere transfer</label><label className="adaptive-stack adaptive-label">İzin verilen adresler (her satıra bir adres)<textarea rows={3} className="adaptive-input policy-address" value={allowed} onChange={e=>setAllowed(e.target.value)}/></label>{restricted&&!allowed.trim()&&<p className="adaptive-status adaptive-status-warning">İzin listesi boşsa hiçbir alıcıya transfer yapılamaz.</p>}<label className="adaptive-stack adaptive-label">Yasaklanan adresler (her satıra bir adres)<textarea rows={3} className="adaptive-input policy-address" value={denied} onChange={e=>setDenied(e.target.value)}/></label><p className="adaptive-small">Yasak listesi izin listesinden önceliklidir. Adres biçimi kontrolü, adresin gerçek sahibini doğrulamaz.</p>{error&&<p role="alert" className="adaptive-status adaptive-status-danger">{error}</p>}{notice&&<p role="status" className="adaptive-status adaptive-status-success">{notice}</p>}<button type="button" className="adaptive-button adaptive-button-primary" disabled={agent.status==='revoked'} onClick={save}><Save size={20}/> Agent kurallarını kaydet</button></section>;
}
function RequestSimulator({agent}:{agent:Agent}){
 const {request}=useDemoVault();const {preferences}=useAdaptive();const [amount,setAmount]=useState('10'),[recipient,setRecipient]=useState(DEMO_RECIPIENT),[identity,setIdentity]=useState('Örnek alıcı'),[matching,setMatching]=useState(true),[result,setResult]=useState<{ok:boolean;text:string}|null>(null);
 function send(){try{const units=readAmount(amount);if(!units||!validAddress(recipient.trim())||!identity.trim())throw Error('Pozitif tutar, geçerli alıcı adresi ve alıcı etiketi gerekli.');const r=request(agent.id,units/CENT,recipient.trim(),identity.trim(),matching);setResult({ok:r.decision==='approved',text:r.decision==='approved'?'Demo transferi gerçekleşti.':`${r.reason?reasonLabel[r.reason]:'Talep reddedildi'}.${r.suspended?' Beşinci ihlal: asistan askıya alındı.':''}`});}catch(e){setResult({ok:false,text:e instanceof Error?e.message:'Talep gönderilemedi.'});}}
 return <section className="adaptive-card adaptive-stack"><div className="adaptive-row"><FlaskConical color="var(--ad-accent)"/><h2 className="adaptive-section-heading">İşlem talebi simülatörü</h2></div><p className="adaptive-small">Gerçek imza veya blockchain işlemi yapılmaz. İmzacı eşleşmesini seçerek kural motorunu test edin. Alıcı etiketi beyan edilen bilgidir.</p><label className="adaptive-stack adaptive-label">Transfer tutarı (USDC)<input className="adaptive-input" inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label className="adaptive-stack adaptive-label">Alıcı adresi<input className="adaptive-input" value={recipient} onChange={e=>setRecipient(e.target.value)}/></label><label className="adaptive-stack adaptive-label">Alıcı etiketi<input className="adaptive-input" maxLength={80} value={identity} onChange={e=>setIdentity(e.target.value)}/></label><label className="adaptive-row"><input type="checkbox" checked={matching} onChange={e=>setMatching(e.target.checked)}/> Demo imzacı eşleşiyor</label><p className="adaptive-small">Durum: {statusLabel[agent.status]} · İhlaller: {agent.violations}/5 · Toplam harcama: {preferences.hideBalance?'••••':money(agent.totalSpent)+' USDC'}</p><button className="adaptive-button adaptive-button-primary" onClick={send}>Demo talebi gönder</button>{result&&<p role="status" className={'adaptive-status '+(result.ok?'adaptive-status-success':'adaptive-status-danger')}>{result.text}</p>}</section>;
}
export default function PoliciesPage(){const {data,freeze,storageAvailable}=useDemoVault();const {preferences}=useAdaptive();const [id,setId]=useState('');const selected=data.vault.agents.find(a=>a.id===id)??data.vault.agents.find(a=>a.status!=='revoked')??data.vault.agents[0];return <div className="adaptive-policies adaptive-stack"><header><p className="adaptive-small">GÜVENLİK MERKEZİ</p><h1 className="adaptive-heading">Güvenliğim</h1><p className="adaptive-description">Her asistan için ayrı güvenlik kuralları belirleyin.</p></header><section className="adaptive-card policy-hero" data-stopped={data.vault.frozen}>{data.vault.frozen?<ShieldAlert size={64}/>:<ShieldCheck size={64}/>}<h2 className="adaptive-section-heading">{data.vault.frozen?'Demo kasa donduruldu':'Demo kuralları etkin'}</h2><p>Gerçek blockchain güvenliği henüz bağlı değildir.</p><button className={'adaptive-button '+(data.vault.frozen?'adaptive-button-secondary':'adaptive-button-danger')} onClick={()=>{if(window.confirm(data.vault.frozen?'Demo kasayı tekrar aç?':'Tüm demo para çıkışları durdurulsun mu?'))freeze(!data.vault.frozen);}}>{data.vault.frozen?'Dondurmayı kaldır':'Kasayı dondur'}</button></section>{!storageAvailable&&<p role="alert" className="adaptive-status adaptive-status-warning">Tarayıcı depolaması kullanılamıyor. Değişiklikler kalıcı olmayabilir.</p>}<section className="adaptive-card adaptive-stack"><div className="adaptive-row"><Bot color="var(--ad-accent)"/><h2 className="adaptive-section-heading">Asistan seçin</h2></div>{selected?<label className="adaptive-stack adaptive-label">Asistan<select className="adaptive-input" value={selected.id} onChange={e=>setId(e.target.value)}>{data.vault.agents.map(a=><option key={a.id} value={a.id}>{data.profiles[a.id].name} · {statusLabel[a.status]}</option>)}</select></label>:<p>Önce Asistanlarım ekranından bir demo asistan ekleyin.</p>}</section>{selected&&<div className="policy-grid"><PolicyEditor key={selected.id} agent={selected}/><RequestSimulator key={selected.id} agent={selected}/></div>}{preferences.mode==='professional'&&<section className="adaptive-card adaptive-stack"><h2 className="adaptive-section-heading">Teknik durum</h2><p>İşlem motoru: TypeScript simülasyonu</p><p>Kriptografik doğrulama: Yok</p><p>Solana bağlantısı: Yok</p><p>Denetim kaydı: Tarayıcı yerel depolaması (değiştirilebilir)</p></section>}</div>;}
